package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoSoundtrackReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun owner(a:HonorableVideoEditorActivity)=dialog().also{set(a,"inspectorReviewDialog",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun prepared():HonorableVideoEditorActivity=activity().also{a->val p=get(a,"project")as VideoEditProject;p.restore(p.segments,soundtrack=p.soundtrack!!.copy(startMs=1000,endMs=9000,volume=.333f,loop=false))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,track:VideoSoundtrack,value:Float?):Boolean{val p=get(a,"project")as VideoEditProject;return call(a,"commitSoundtrackReview",d,r,p,0,p.segments[0],track,value)as Boolean}
 @Test fun volumeChangesOnlyMixLevelAndHasOneUndo(){val a=prepared();val p=get(a,"project")as VideoEditProject;val clips=p.segments;val track=p.soundtrack!!;val d=owner(a);val r=capture(a);assertTrue(commit(a,d,r,track,.75f));assertEquals(track.copy(volume=.75f),p.soundtrack);assertSame(clips,p.segments);assertNull(get(a,"inspectorReviewDialog"));assertTrue(p.undo());assertEquals(track,p.soundtrack);assertEquals(clips,p.segments);assertFalse(p.canUndo);assertFalse(commit(a,d,r,track,0f));assertTrue(p.canRedo)}
 @Test fun removalKeepsClipSourceAudioAndUndoRestoresCompleteTrack(){val a=prepared();val p=get(a,"project")as VideoEditProject;val clips=p.segments;val track=p.soundtrack!!;val d=owner(a);assertTrue(commit(a,d,capture(a),track,null));assertNull(p.soundtrack);assertSame(clips,p.segments);assertTrue(p.undo());assertEquals(track,p.soundtrack);assertEquals(1000L,p.soundtrack!!.startMs);assertEquals(9000L,p.soundtrack!!.endMs);assertFalse(p.soundtrack!!.loop);assertEquals(.333f,p.soundtrack!!.volume);assertFalse(p.canUndo)}
 @Test fun matchingCustomVolumeConsumesWithoutNewHistory(){val a=prepared();val p=get(a,"project")as VideoEditProject;val track=p.soundtrack!!;val d=owner(a);assertTrue(commit(a,d,capture(a),track,.333f));assertSame(track,p.soundtrack);assertFalse(p.canUndo);assertNull(get(a,"inspectorReviewDialog"))}
 @Test fun staleProjectSourceDurationRangeGenerationSessionForegroundRecoveryBusyAndTrackRefuse(){for(flag in listOf("pause","source","duration","selection","generation","mode","recovery","busy","analysis","music")){val a=prepared();val p=get(a,"project")as VideoEditProject;val track=p.soundtrack!!;val d=owner(a);val r=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"selection"->set(a,"selectedClip",1);"generation"->set(a,"captionReviewGeneration",r.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);else->p.setSoundtrack(track.copy(startMs=2000))};val before=p.soundtrack;assertFalse(flag,commit(a,d,r,track,null));assertSame(before,p.soundtrack);assertNull(get(a,"inspectorReviewDialog"))}}
 @Test fun oldHiddenAndUntrackedDialogsCannotConsumeCurrentSoundtrackOwner(){for(flag in listOf("old","hidden","untracked")){val a=prepared();val p=get(a,"project")as VideoEditProject;val track=p.soundtrack!!;val old=owner(a);val r=capture(a);val next=if(flag=="old")owner(a)else null;when(flag){"hidden"->showing(old,false);"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>())};assertFalse(commit(a,old,r,track,.5f));assertSame(track,p.soundtrack);assertFalse(p.canUndo);if(next!=null){assertSame(next,get(a,"inspectorReviewDialog"));assertTrue(commit(a,next,r,track,.5f))}}}
 @Test fun invalidVolumeOrWrongCapturedTrackKeepsOwnerForCorrection(){val a=prepared();val p=get(a,"project")as VideoEditProject;val track=p.soundtrack!!;val d=owner(a);val r=capture(a);for(value in listOf(-1f,2f,Float.NaN,Float.POSITIVE_INFINITY)){try{commit(a,d,r,track,value);fail("accepted") }catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(track,p.soundtrack);assertSame(d,get(a,"inspectorReviewDialog"));assertFalse(p.canUndo)};try{commit(a,d,r,track.copy(volume=.1f),.5f);fail("wrong track") }catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertTrue(commit(a,d,r,track,.5f));assertTrue(p.undo());assertEquals(track,p.soundtrack)}
 @Test fun excerptLoopAndCustomVolumeSurviveExistingProjectCodec(){val a=prepared();val p=get(a,"project")as VideoEditProject;val track=p.soundtrack!!;val d=owner(a);assertTrue(commit(a,d,capture(a),track,.777f));val draft=VideoDraft(5000,p.segments,0,0,0,5000,soundtrack=p.soundtrack);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertEquals(track.copy(volume=.777f),p.soundtrack)}
 @Test fun pausedBusyAndRecoveryEntriesReturnBeforeSoundtrackWidgets(){for(remove in listOf(true,false))for(flag in listOf("pause","busy","recovery")){val a=prepared();when(flag){"pause"->set(a,"workspaceActive",false);"busy"->set(a,"saving",true);else->set(a,"recoveryBytes",byteArrayOf(1))};call(a,"chooseSoundtrackAudio",remove);assertNull(get(a,"inspectorReviewDialog"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
